import {createFeatures} from './features.js?v=20260924-features2';
import {makeState,today,addDays,nights,validStay,roomStatus,available,rate,createBooking,setRoomOpen,saveEasyfo,confirmBooking,cancelBooking,FLOORS,CLOSE_REASONS,audit,requireAdmin,setRoomsOpen,closeReason,moveBooking,updateRoom,saveRoomOrder,parseRoomCSV,validateRoomImport,importRooms} from './model.js?v=20260924-features2';
let state=makeState();
let view='guest',section='inventory',typeFilter='all',statusFilter='all',bookingFilter='all',page=1;
let floorFilter=3,masterFloor=3,masterMode='catalog',roomQuery='',layoutDraft={},pendingBatch=null,importPreview=null;
const selectedRooms=new Set();
let search={start:state.start,end:state.end,guests:2,type:'all'},range={start:state.start,end:state.end};
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),content=document.querySelector('#dialog-content');
const money=v=>Number(v).toLocaleString('th-TH');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>new Date(d+'T00:00:00').toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'2-digit'});
const typeBy=id=>state.types.find(t=>t.id===id);
const statusNames={open:'เปิดขาย',closed:'ปิดขาย',pending:'รอยืนยัน',confirmed:'ยืนยันแล้ว',cancelled:'ยกเลิกแล้ว'};
const badge=s=>`<span class="badge ${s}">${statusNames[s]}</span>`;
const paths={bed:'M3 18v-7m18 7v-7M3 14h18M5 11V7h14v4M3 18v3m18-3v3',calendar:'M5 5h14a1 1 0 0 1 1 1v14H4V6a1 1 0 0 1 1-1zm2-3v5m10-5v5M4 10h16',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m7-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8m9-8a4 4 0 0 1 0 8m4 10v-2a4 4 0 0 0-3-3.87',size:'M4 9V4h5m6 0h5v5M4 15v5h5m6 0h5v-5',check:'M5 12l4 4L19 6',grid:'M3 3h7v7H3zm11 0h7v7h-7zM3 14h7v7H3zm11 0h7v7h-7z',list:'M8 6h13M8 12h13M8 18h13M3 6h.01M3 12h.01M3 18h.01',edit:'M12 20h9M16 3a2.12 2.12 0 0 1 3 3L7 18l-4 1 1-4z',info:'M12 16v-4m0-4h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',arrow:'M5 12h14m-6-6 6 6-6 6',lock:'M5 10h14v11H5zm3 0V6a4 4 0 0 1 8 0v4',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',leaf:'M20 3C8 2 2 8 5 16c8 5 16-1 15-13M4 21 15 10'};
const icon=(name,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;
const features=createFeatures({getState:()=>state,getSearch:()=>search,setSearch:value=>{search=value},render,navigate,modal,header,dialog,toast,esc,money,fmt,icon,doc:document});
let toastTimer;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3500)}
function header(title,subtitle=''){return `<div class="modal-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div><button class="close-modal" data-action="close" aria-label="ปิดหน้าต่าง">×</button></div>`}
function modal(html){dialog.classList.remove('feature-wide');content.innerHTML=html;if(!dialog.open)dialog.showModal();else dialog.scrollTop=0}
function error(message){const el=content.querySelector('.form-error');if(el)el.textContent=message;else toast(message)}
function render(){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view))});document.querySelector('#pending-count').textContent=state.bookings.filter(b=>b.status==='pending').length;app.innerHTML=view==='guest'?guest():view==='widget'?features.widgetPage():front()}
function navigate(next,sub){if(view!==next)selectedRooms.clear();view=next;if(sub)section=sub;render();window.scrollTo({top:0,behavior:'instant'})}
function dateFields(values,prefix=''){return `<label>วันเช็กอิน<input aria-label="วันเช็กอิน${prefix}" name="start" type="date" min="${today()}" value="${values.start}" required></label><label>วันเช็กเอาต์<input aria-label="วันเช็กเอาต์${prefix}" name="end" type="date" min="${addDays(values.start,1)}" value="${values.end}" required></label>`}
function guest(){return `<section class="hero"><div class="hero-copy"><div class="eyebrow">YOUR NEXT STAY, MADE SIMPLE</div><h1>วันพักผ่อนที่ดี<br>เริ่มต้นที่ห้องพักของคุณ</h1><p>เลือกห้องที่ชอบ จองง่ายผ่านเว็บไซต์<br>แล้วชำระเงินเมื่อมาถึงโรงแรม</p><div class="hero-points"><span>${icon('check',15)} จองตรงกับโรงแรม</span><span>${icon('check',15)} ชำระเงินที่โรงแรม</span></div></div><div class="hero-image"><img src="./assets/room.png" alt="ภาพห้องพักสมมติ เตียงสีขาวและผนังหัวเตียงสีน้ำเงิน" fetchpriority="high"><span class="image-label">A LITTLE SPACE TO UNWIND</span><span class="image-note">ภาพประกอบสมมติ</span></div></section>
 <div class="container search-wrap"><form id="search-form" class="search-box">${dateFields(search)}<label>ผู้เข้าพัก<select name="guests">${[1,2,3,4].map(n=>`<option value="${n}" ${search.guests===n?'selected':''}>${n} ท่าน / ห้อง</option>`).join('')}</select></label><label>ประเภทห้อง<select name="type"><option value="all">ทุกประเภท</option>${state.types.map(t=>`<option value="${t.id}" ${search.type===t.id?'selected':''}>${t.name}</option>`).join('')}</select></label><button class="primary" type="submit">ค้นหาห้องพัก ${icon('arrow')}</button></form><div class="booking-benefits"><span>${icon('lock',13)} ยังไม่ต้องชำระเงินออนไลน์</span><span>${icon('clock',13)} รอพนักงานยืนยันการจอง</span><span>จองครั้งละ 1 ห้อง</span></div></div>
 ${features.consentBanner()}<section class="container rooms-section" id="rooms">${features.toolbar()}${features.calendar()}<div class="section-heading"><div><div class="eyebrow">ROOMS & SUITES</div><h2>เลือกห้องพักของคุณ</h2><p>${fmt(search.start)} — ${fmt(search.end)} · ${nights(search.start,search.end)} คืน · ${search.guests} ท่าน</p></div><span class="outline-pill">ราคาและรายละเอียดเป็นข้อมูลตัวอย่าง</span></div><div class="room-list">${state.types.filter(t=>t.capacity>=search.guests&&(!search.type||search.type==='all'||t.id===search.type)).map(roomCard).join('')||`<div class="empty"><h3>ไม่พบห้องที่ตรงกับการค้นหา</h3><p>ลองเปลี่ยนจำนวนผู้เข้าพักหรือวันที่อีกครั้ง</p></div>`}</div>${features.compareTray()}<div class="flow-note">${icon('info',20)}<div><strong>จองแล้ว พนักงานจะช่วยดูแลต่อ</strong><br>เมื่อส่งคำขอ ระบบจะกันห้องในเว็บไซต์ไว้ระหว่างรอยืนยัน พนักงานตรวจสอบและลงรายการใน Easyfo ก่อนยืนยันการจอง</div></div></section><footer class="footer"><div class="container"><span><strong>Suntara Grand</strong> · ตัวอย่างระบบจองห้องพัก<br><button class="text-button consent-footer" data-action="feature-manage-consent">ตั้งค่าสถิติการใช้งาน</button></span><span>ภาพ ราคา สิ่งอำนวยความสะดวก และหมายเลขห้องเป็นข้อมูลสมมติทั้งหมด</span></div></footer>`}
function roomCard(t){const free=available(state,t.id,search.start,search.end).length;return `<article class="room-card"><div class="room-photo"><img src="${esc(t.photo)}" alt="ภาพประกอบสมมติห้อง ${t.name}" loading="lazy" style="object-position:${t.id==='grand'?'30%':t.id==='suite'?'80%':'50%'} center">${t.discount?`<span class="badge">ข้อเสนอพิเศษ · ลด ${t.discount}%</span>`:''}<span class="photo-caption">ภาพประกอบสมมติ</span></div><div class="room-body"><div class="room-title"><div><h3>${t.name}</h3><p class="room-subtitle">${esc(t.label)}</p></div>${free?'<span class="badge open">พร้อมจอง</span>':'<span class="badge closed">เต็มในช่วงนี้</span>'}</div><div class="room-facts"><span>${icon('size',15)} ${t.area} ตร.ม.</span><span>${icon('users',15)} สูงสุด ${t.capacity} ท่าน</span><span>${icon('bed',15)} ${t.bed}</span></div><div class="room-price"><div>${t.discount?`<div class="old-price">฿${money(t.price)}</div>`:''}<div class="price">฿${money(rate(t))} <span class="per-night">/ คืน</span></div><div class="total-hint">${nights(search.start,search.end)} คืน รวม ฿${money(rate(t)*nights(search.start,search.end))}</div></div><div class="card-actions"><button class="primary" data-action="book" data-id="${t.id}" ${!free?'disabled':''}>เลือกห้องนี้ ${icon('arrow',16)}</button><button class="text-button" data-action="detail" data-id="${t.id}">ดูรายละเอียดห้อง</button></div></div></div>${features.compareButton(t.id)}</article>`}
function front(){
 const pending=state.bookings.filter(b=>b.status==='pending').length;
 const menus=[['inventory','grid','ห้องเปิดขาย'],['bookings','list','รายการจอง'],['settings','edit','ราคาและข้อมูลห้อง'],['master','bed','ตั้งค่าห้องและผัง'],['analytics','grid','สถิติการจอง'],['audit','clock','ประวัติการเปลี่ยนแปลง'],['guide','info','ขั้นตอนการทำงาน']];
 return `<div class="front-layout"><aside class="sidebar"><div class="eyebrow">FRONT DESK WORKSPACE</div>${menus.map(([id,ic,label])=>`<button class="side-button ${section===id?'active':''}" data-action="section" data-id="${id}" aria-pressed="${section===id}">${icon(ic,18)} ${label}${id==='bookings'?`<span class="count">${pending}</span>`:''}</button>`).join('')}<div class="sidebar-bottom"><img class="sidebar-logo" src="./assets/suntara-logo.png" width="136" height="132" style="object-fit:contain" alt="Suntara Grand"><div>168 ห้อง · ชั้น 3–6<br>ผังและหมายเลขห้องสมมติ</div></div></aside><div class="workspace"><div class="workspace-top"><div class="breadcrumb">Suntara Grand / หลังบ้าน Front</div><label class="role-control">บทบาททดลอง<select id="demo-role"><option value="front" ${state.role==='front'?'selected':''}>Front Demo</option><option value="admin" ${state.role==='admin'?'selected':''}>ผู้ดูแล Demo</option></select></label></div>${section==='inventory'?inventory():section==='bookings'?bookings():section==='settings'?settings():section==='master'?master():section==='analytics'?features.analyticsPage():section==='audit'?auditView():guide()}</div></div>`;
}
function pageTitle(title,desc){return `<div class="page-title"><div><h1>${title}</h1><p>${desc}</p></div><span class="sample-tag">โหมดตัวอย่าง</span></div>`}
function floorTabs(value,action,all=true){return `<div class="floor-tabs" aria-label="เลือกชั้น">${(all?['all',...FLOORS]:FLOORS).map(f=>{const rooms=state.rooms.filter(r=>f==='all'||r.floor===f);return `<button class="${String(value)===String(f)?'active':''}" data-action="${action}" data-id="${f}" aria-pressed="${String(value)===String(f)}"><strong>${f==='all'?'ทุกชั้น':'ชั้น '+f}</strong><span>${rooms.length} ห้อง</span></button>`}).join('')}</div>`}
function filteredRooms(){return state.rooms.filter(r=>(floorFilter==='all'||r.floor===Number(floorFilter))&&(typeFilter==='all'||r.type===typeFilter)&&(statusFilter==='all'||roomStatus(state,r,range.start,range.end)===statusFilter)&&r.id.toLowerCase().includes(roomQuery.toLowerCase())).sort((a,b)=>a.floor-b.floor||a.order-b.order)}
function selectableRoom(r){return ['open','closed'].includes(roomStatus(state,r,range.start,range.end))}
function inventory(){
 const statuses=state.rooms.map(r=>roomStatus(state,r,range.start,range.end)),all=filteredRooms(),pages=Math.max(1,Math.ceil(all.length/16));page=Math.min(page,pages);
 const selectable=all.filter(selectableRoom),allSelected=selectable.length>0&&selectable.every(r=>selectedRooms.has(r.id));
 return `${pageTitle('จัดการห้องเปิดขาย','เลือกชั้นและช่วงวันที่ แล้วจัดการทีละห้องหรือหลายห้องพร้อมกัน')}<div class="notice">${icon('info')}<div><strong>ตรวจ Easyfo ก่อนเปิดขาย</strong> · ห้องจากช่องทางอื่นไม่ซิงก์อัตโนมัติ สถานะนี้ใช้สำหรับขายออนไลน์ และแยกจากสถานะแม่บ้าน</div></div><div class="overview-label">ภาพรวมทุกชั้น · ${fmt(range.start)} — ${fmt(range.end)} · ${nights(range.start,range.end)} คืน</div><div class="stats">${[['open','พร้อมขายออนไลน์','ว่างครบทุกคืนที่เลือก'],['pending','รอพนักงานยืนยัน','กันห้องในเว็บไซต์แล้ว'],['confirmed','ยืนยันแล้ว','ลงรายการใน Easyfo แล้ว'],['closed','ปิดขายออนไลน์','ปิดอย่างน้อย 1 คืนในช่วงนี้']].map(([s,title,foot])=>`<div class="stat"><div class="stat-label"><span class="dot ${s}"></span>${title}</div><div class="stat-number">${statuses.filter(x=>x===s).length}<small>ห้อง</small></div><div class="stat-foot">${foot}</div></div>`).join('')}</div><div class="type-summary">${state.types.map(t=>`<div><span>${t.name}</span><strong>${available(state,t.id,range.start,range.end).length}<small> / ${t.count}</small></strong><small>พร้อมขาย / ห้องทั้งหมด</small></div>`).join('')}</div><section class="panel"><div class="panel-head"><div><h2>ห้องพักตามชั้น</h2><p>ตัวอย่าง 168 ห้อง · ยังไม่ใช่เลขห้องและสัดส่วนจริง</p></div><span class="badge">${selectedRooms.size} ห้องที่เลือก</span></div><div class="inventory-date"><form class="date-toolbar" id="range-form">${dateFields(range,'สำหรับจัดการห้อง')}<button class="secondary">ดูสถานะ</button></form><div class="date-caption">ไม่รวมคืนวันเช็กเอาต์<br>เปลี่ยนช่วงวันที่แล้วกด “ดูสถานะ”</div></div>${floorTabs(floorFilter,'floor')}<div class="filters inventory-filters"><div class="type-tabs">${[['all','ทุกประเภท'],...state.types.map(t=>[t.id,t.name])].map(([id,n])=>`<button class="${typeFilter===id?'active':''}" data-action="type" data-id="${id}">${n}</button>`).join('')}</div><div class="room-search-controls"><form id="room-search" class="room-search"><input name="query" value="${esc(roomQuery)}" maxlength="12" aria-label="ค้นหาเลขห้อง" placeholder="ค้นหาเลขห้อง"><button class="secondary" aria-label="ค้นหาห้อง">ค้นหา</button></form><select id="status-filter" aria-label="กรองสถานะห้อง">${[['all','ทุกสถานะ'],...Object.entries(statusNames).filter(([s])=>s!=='cancelled')].map(([s,n])=>`<option value="${s}" ${statusFilter===s?'selected':''}>${n}</option>`).join('')}</select></div></div><div class="bulk-bar"><label class="bulk-select"><input type="checkbox" id="select-filtered" ${allSelected?'checked':''} ${!selectable.length?'disabled':''}>เลือกห้องที่จัดการได้ในผลลัพธ์นี้ (${selectable.length})</label><div class="bulk-actions"><span>${selectedRooms.size} ห้อง</span><button class="secondary" data-action="clear-selection" ${!selectedRooms.size?'disabled':''}>ล้าง</button><button class="secondary" data-action="bulk" data-open="false" ${!selectedRooms.size?'disabled':''}>ปิดขาย</button><button class="primary" data-action="bulk" data-open="true" ${!selectedRooms.size?'disabled':''}>เปิดขาย</button></div></div><div class="room-grid">${all.slice((page-1)*16,page*16).map(r=>{const s=roomStatus(state,r,range.start,range.end),can=selectableRoom(r);return `<article class="room-tile ${s} ${selectedRooms.has(r.id)?'selected':''}"><label class="room-select" title="${can?'เลือกห้อง '+r.id:'มีรายการจองอยู่'}"><input type="checkbox" data-room-select="${esc(r.id)}" aria-label="เลือกห้อง ${esc(r.id)}" ${selectedRooms.has(r.id)?'checked':''} ${!can?'disabled':''}></label><button class="room-content" data-action="room" data-id="${esc(r.id)}"><div class="tile-top"><span class="room-number">${esc(r.id)}</span></div><div class="room-type">${typeBy(r.type).name}</div><div class="room-floor">ชั้น ${r.floor}</div><div class="tile-status"><span class="dot ${s}"></span>${statusNames[s]}</div></button></article>`}).join('')||'<div class="empty">ไม่มีห้องที่ตรงกับตัวกรองนี้<br><button class="text-button" data-action="clear-filters">ล้างตัวกรอง</button></div>'}</div><div class="grid-bottom"><span>แสดง ${all.length?(page-1)*16+1:0}–${Math.min(page*16,all.length)} จาก ${all.length} ห้อง</span><div class="pagination"><button data-action="prev" ${page===1?'disabled':''} aria-label="หน้าก่อนหน้า">‹</button><span>${page} / ${pages}</span><button data-action="next" ${page===pages?'disabled':''} aria-label="หน้าถัดไป">›</button></div></div></section><p class="front-foot">ห้องรอยืนยันและห้องที่ยืนยันแล้วจะเลือกเปิด–ปิดขายทับไม่ได้ · การแก้ไขมีผลเฉพาะช่วงวันที่ระบุ</p>`;
}

function bookings(){const list=state.bookings.filter(b=>bookingFilter==='all'||b.status===bookingFilter);return `${pageTitle('รายการจอง','ตรวจสอบคำขอ ลงรายการใน Easyfo แล้วจึงยืนยันการจอง')}<div class="notice amber">${icon('clock')}<div>มี <strong>${state.bookings.filter(b=>b.status==='pending').length} รายการรอยืนยัน</strong> · รายการเหล่านี้ถูกกันห้องในเว็บไซต์แล้ว ลูกค้ายังไม่ต้องชำระเงิน</div></div><section class="panel"><div class="panel-head"><div><h2>การจองผ่านเว็บไซต์</h2><p>สถานะการจอง การลง Easyfo และการชำระเงิน แสดงแยกกัน</p></div><span class="outline-pill">${state.bookings.length} รายการ</span></div><div class="booking-tabs">${[['all','ทั้งหมด'],['pending','รอยืนยัน'],['confirmed','ยืนยันแล้ว'],['cancelled','ยกเลิก']].map(([s,n])=>`<button data-action="booking-filter" data-id="${s}" class="${bookingFilter===s?'active':''}">${n}</button>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>ผู้จอง / เลขที่</th><th>ห้องพัก</th><th>วันเข้าพัก</th><th>สถานะการจอง</th><th>Easyfo</th><th>การชำระเงิน</th><th></th></tr></thead><tbody>${list.map(b=>`<tr><td><div class="table-name">${esc(b.name)}</div><div class="table-sub">${b.id}</div></td><td>${typeBy(b.type).name}<div class="table-sub">ห้อง ${esc(b.room)} · ชั้น ${state.rooms.find(r=>r.id===b.room)?.floor??'—'} · ${b.guests} ท่าน</div></td><td>${fmt(b.start)}<div class="table-sub">ถึง ${fmt(b.end)} · ${nights(b.start,b.end)} คืน</div></td><td>${badge(b.status)}</td><td>${b.easyfo?'<span class="badge open">ลงแล้ว</span>':'<span class="table-sub">ยังไม่ลงรายการ</span>'}</td><td><div>฿${money(b.total)}</div><div class="table-sub">${b.status==='cancelled'?'ไม่มีการรับชำระ':'ยังไม่ชำระ · จ่ายที่โรงแรม'}</div></td><td><button class="table-action" data-action="booking" data-id="${b.id}">ดูรายการ →</button></td></tr>`).join('')||'<tr><td colspan="7" style="text-align:center;padding:40px">ไม่มีรายการในสถานะนี้</td></tr>'}</tbody></table></div></section><div class="flow-note">${icon('info')}<div>ลองจองจาก “หน้าจองลูกค้า” แล้วกลับมาที่หน้านี้ รายการใหม่จะปรากฏให้ทดลองจัดการได้ทันที</div></div>`}
function settings(){return `${pageTitle('ราคาและข้อมูลห้อง','จัดการราคา โปรโมชั่น และรายละเอียดที่ลูกค้าจะเห็น')}${adminNotice()}<div class="notice">${icon('info')}<div>การแก้ไขในต้นแบบนี้จะแสดงบนหน้าลูกค้าทันที ใช้ราคาเดียวต่อประเภทห้องทุกวัน และคืนค่าทั้งหมดเมื่อรีเฟรชหน้า</div></div><div class="settings-grid">${state.types.map(t=>`<article class="settings-card"><div class="settings-card-head"><img src="${esc(t.photo)}" alt="ภาพห้อง ${t.name} สมมติ"><div><h3>${t.name}</h3><p>${t.count} ห้องตัวอย่าง · สูงสุด ${t.capacity} ท่าน</p></div></div><div class="settings-card-body"><div class="settings-price"><div><div class="tiny">ราคาขาย / คืน</div><strong>฿${money(rate(t))}</strong>${t.discount?` <span class="old-price">฿${money(t.price)}</span>`:''}</div><span class="badge ${t.discount?'open':'closed'}" style="align-self:center">${t.discount?'ส่วนลด '+t.discount+'%':'ราคาปกติ'}</span></div><button class="secondary" data-action="edit" data-id="${t.id}" ${state.role==='admin'?'':'disabled'}>${icon('edit',16)} แก้ไขราคาและรายละเอียด</button></div></article>`).join('')}</div><p class="front-foot">ราคาของรายการจองเดิมจะคงเดิมเมื่อแก้ไขราคาใหม่ · รูปที่เลือกในตัวอย่างจะไม่ถูกอัปโหลดไปยังเซิร์ฟเวอร์</p>`}
function guide(){return `${pageTitle('ลองระบบภายใน 5 นาที','สาธิตตั้งแต่เลือกห้องจน Front ยืนยัน พร้อมจัดการห้องแยกชั้น')}<div class="walkthrough"><article class="step"><div class="step-num">01</div><h3>Front เปิดห้องขาย</h3><p>เลือกช่วงวันที่และชั้น 3–6 คลิกดูห้องหรือติ๊กหลายห้อง ตรวจ Easyfo แล้วกดเปิดขายพร้อมกันได้</p><button class="text-button" data-action="section" data-id="inventory">ทดลองจัดการห้อง →</button></article><article class="step"><div class="step-num">02</div><h3>ลูกค้าส่งคำขอจอง</h3><p>เลือกวันและประเภทห้อง ใช้ข้อมูลสมมติที่กรอกไว้ ระบบกันห้องที่ว่างครบทุกคืนระหว่างรอยืนยัน</p><button class="text-button" data-action="guest">ทดลองจองห้องพัก →</button></article><article class="step"><div class="step-num">03</div><h3>ลง Easyfo และยืนยัน</h3><p>Front ตรวจหรือเปลี่ยนเลขห้อง ลงรายการใน Easyfo ด้วยตนเอง กรอกเลขอ้างอิง แล้วกดยืนยัน ลูกค้าจ่ายที่โรงแรม</p><button class="text-button" data-action="section" data-id="bookings">ทดลองยืนยันรายการ →</button></article></div><section class="panel guide-info"><div class="panel-head"><h2>ลองความสามารถเพิ่มเติม</h2></div><div class="guide-checklist"><ol><li>หน้าลูกค้า: เปิดปฏิทิน เลือกวันเข้าและวันออก แล้วกดใช้ช่วงวันที่นี้</li><li>กดเปรียบเทียบห้อง เลือก 2–4 ประเภท และจองจากตารางได้</li><li>แท็บ “เว็บหลัก (ตัวอย่าง)” แสดงปุ่มจองที่พามาหน้าจองลูกค้า</li><li>ยอมรับสถิติ แล้วลองค้นหา ดูห้อง เริ่มกรอก และส่งคำขอ เปิด “สถิติการจอง → การทดลองครั้งนี้” เพื่อดูเหตุการณ์ โดยไม่มีการส่งข้อมูลไป Google</li><li>เปิด “ห้องเปิดขาย” เลือกชั้นและติ๊กหลายห้อง กดปิดขาย ระบุเหตุผล แล้วดูผลบนหน้าลูกค้า</li><li>เปิด “ประวัติการเปลี่ยนแปลง” เพื่อดูชื่อบทบาท เวลา และรายละเอียดที่บันทึก</li><li>สลับบทบาททดลองด้านบนเป็น “ผู้ดูแล Demo” เพื่อแก้ราคาและส่วนลด</li><li>เปิด “ตั้งค่าห้องและผัง” แก้ข้อมูลรายห้อง หรือเข้า “จัดลำดับผัง” แล้วลากการ์ดหรือใช้ลูกศร ก่อนกดบันทึก</li><li>ดาวน์โหลด CSV ตัวอย่าง 168 ห้อง เปิดด้วย Excel แล้วบันทึกเป็น CSV UTF-8 เพื่อลองนำเข้า ระบบตรวจเลขซ้ำ ชั้น ประเภท และผลต่อรายการจองก่อนบันทึก</li></ol><p>กด “เริ่มตัวอย่างใหม่” ด้านบนเพื่อคืนข้อมูลเริ่มต้นได้ทุกเวลา</p></div></section><div class="notice amber guide-info">${icon('info')}<div><strong>Demo สำหรับพิจารณาก่อนพัฒนาใช้งานจริง</strong><br>ชื่อและโลโก้โรงแรมมาจากผู้เสนอ ส่วนเลขห้อง สัดส่วนแต่ละชั้น ราคา รูปห้อง และรายละเอียดเป็นข้อมูลสมมติ ยังไม่มีฐานข้อมูล ล็อกอินจริง การแจ้งเตือน หรือการเชื่อม Easyfo ข้อมูลแยกกันในแต่ละหน้าเว็บและหายเมื่อรีเฟรช</div></div>`}
function showDetail(id){features.record('view_room',id);const t=typeBy(id);modal(header(t.name,'รายละเอียดและรูปภาพสมมติ')+`<div class="modal-body"><img class="modal-photo" src="${esc(t.photo)}" alt="ภาพประกอบสมมติห้อง ${t.name}"><p>${esc(t.desc)}</p><div class="room-facts"><span>${icon('size')} ${t.area} ตร.ม.</span><span>${icon('users')} สูงสุด ${t.capacity} ท่าน</span><span>${icon('bed')} ${t.bed}</span></div><div class="status-help">สิ่งอำนวยความสะดวกตัวอย่าง: Wi-Fi · เครื่องปรับอากาศ · ทีวี · ห้องน้ำส่วนตัว</div><p class="tiny" style="margin-top:13px">รายละเอียดจริงและเงื่อนไขการเข้าพักจะกำหนดร่วมกับโรงแรมก่อนเปิดใช้งาน</p><div class="modal-actions"><button class="secondary" data-action="close">กลับไปเลือกห้อง</button><button class="primary" data-action="book" data-id="${id}" ${!available(state,id,search.start,search.end).length?'disabled':''}>จองห้องนี้</button></div></div>`)}
function showBook(id){const t=typeBy(id);if(t.capacity<search.guests)return toast('จำนวนผู้เข้าพักเกินความจุของห้อง');if(!available(state,id,search.start,search.end).length)return toast('ห้องเต็มในช่วงวันที่เลือก');features.record('begin_booking',id);modal(header('จองห้อง '+t.name,'คำขอตัวอย่าง · ชำระเงินเมื่อถึงโรงแรม')+`<form id="book-form" class="modal-body" data-id="${id}"><div class="notice" style="margin-bottom:20px">${icon('info',17)} ใช้ข้อมูลสมมติที่กรอกไว้เพื่อทดลองได้เลย</div><div class="form-grid"><label>ชื่อผู้จอง<input name="name" value="ลูกค้าทดลอง" maxlength="80" required autocomplete="off"></label><label>เบอร์โทรศัพท์<input name="phone" value="0800000000" inputmode="tel" pattern="0[0-9]{8,9}" required autocomplete="off"></label></div><div class="summary-box"><div class="summary-row"><span>วันเช็กอิน</span><strong>${fmt(search.start)}</strong></div><div class="summary-row"><span>วันเช็กเอาต์</span><strong>${fmt(search.end)}</strong></div><div class="summary-row"><span>การเข้าพัก</span><span>${nights(search.start,search.end)} คืน · ${search.guests} ท่าน · 1 ห้อง</span></div><div class="summary-row"><span>ราคา / คืน</span><span>฿${money(rate(t))}</span></div><div class="summary-row summary-total"><span>ยอดชำระที่โรงแรม</span><strong>฿${money(rate(t)*nights(search.start,search.end))}</strong></div></div><p class="tiny">ยอดนี้เป็นราคาตัวอย่างทั้งหมด ไม่มีการรับชำระเงินจริง</p><label class="check-label"><input type="checkbox" required><span>เข้าใจว่านี่คือการทดลองจอง และรายการจะอยู่ในสถานะรอพนักงานยืนยัน</span></label><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">ย้อนกลับ</button><button class="primary">ส่งคำขอตัวอย่าง ${icon('arrow',16)}</button></div></form>`)}
function bookingSuccess(b){modal(header('ส่งคำขอตัวอย่างแล้ว','ยังไม่ใช่การยืนยันห้องพักจริง')+`<div class="modal-body"><div class="success-mark">✓</div><div class="center"><h3>รอพนักงานยืนยัน</h3><p>ระบบกันห้องในเว็บไซต์ตัวอย่างไว้แล้ว<br>เลขที่รายการ <strong>${b.id}</strong></p></div><div class="summary-box"><div class="summary-row"><span>ห้องพัก</span><strong>${typeBy(b.type).name}</strong></div><div class="summary-row"><span>วันที่เข้าพัก</span><span>${fmt(b.start)} — ${fmt(b.end)}</span></div><div class="summary-row"><span>ชำระที่โรงแรม</span><strong>฿${money(b.total)}</strong></div></div><p class="tiny">ไม่มีการส่งอีเมลหรือข้อความจริงในตัวอย่างนี้</p><div class="modal-actions"><button class="secondary" data-action="close">กลับหน้าลูกค้า</button><button class="primary" data-action="open-front-booking" data-id="${b.id}">ดูรายการนี้ฝั่ง Front →</button></div></div>`)}
function showBooking(id){const b=state.bookings.find(x=>x.id===id);modal(header(b.id,'รายละเอียดการจองตัวอย่าง')+`<div class="modal-body"><div class="info-list"><div class="info-item"><span>ผู้จอง</span><strong>${esc(b.name)}</strong></div><div class="info-item"><span>ห้องพัก</span><strong>${typeBy(b.type).name} · ห้อง ${esc(b.room)} · ชั้น ${state.rooms.find(r=>r.id===b.room)?.floor??'—'}</strong></div><div class="info-item"><span>วันที่เข้าพัก</span><strong>${fmt(b.start)} — ${fmt(b.end)}</strong></div><div class="info-item"><span>สถานะการจอง</span>${badge(b.status)}</div>${b.status!=='cancelled'?`<button class="text-button" data-action="move-booking" data-id="${b.id}">เปลี่ยนห้องพัก →</button>`:''}<div class="info-item"><span>ยอดชำระที่โรงแรม</span><strong>฿${money(b.total)} <span class="tiny">· ยังไม่ชำระ</span></strong></div></div>${b.status==='cancelled'?`<div class="notice amber">${icon('info')}<div>ยกเลิกรายการในเว็บไซต์แล้ว${b.easyfo?' โปรดปรับรายการใน Easyfo ด้วยตนเองด้วย':''}</div></div>`:`<form id="easyfo-form" data-id="${b.id}" class="easyfo-section"><h3>${b.easyfo?'✓ ลงรายการใน Easyfo แล้ว':'1. ลงรายการใน Easyfo ด้วยตนเอง'}</h3><p>กรอกเลขอ้างอิงหลังลงรายการเสร็จ เพื่อให้พนักงานกะถัดไปตรวจสอบได้</p><label>เลขอ้างอิง Easyfo<input name="reference" value="${esc(b.easyfo)}" placeholder="ตัวอย่าง EF-DEMO-001" required maxlength="60" ${b.status==='confirmed'?'readonly':''}></label>${b.status==='pending'?`<button class="secondary">${b.easyfo?'อัปเดตเลขอ้างอิง':'บันทึกว่าลง Easyfo แล้ว'}</button>`:''}</form>`}<div class="form-error" role="alert"></div>${b.status==='pending'?`<div class="modal-actions"><button class="danger" data-action="cancel-prompt" data-id="${b.id}">ยกเลิกรายการ</button><button class="primary" data-action="confirm" data-id="${b.id}" ${!b.easyfo?'disabled':''}>2. ยืนยันการจอง</button></div>${!b.easyfo?'<p class="tiny" style="margin-top:13px;text-align:right">บันทึกการลง Easyfo ก่อน เพื่อเปิดปุ่มยืนยัน</p>':''}`:b.status==='confirmed'?`<div class="status-help">${icon('check',16)} ยืนยันการจองในตัวอย่างแล้ว · ลูกค้าชำระเงินเมื่อถึงโรงแรม</div><div class="modal-actions"><button class="danger" data-action="cancel-prompt" data-id="${b.id}">ยกเลิกรายการ</button><button class="secondary" data-action="close">ปิดหน้าต่าง</button></div>`:'<div class="modal-actions"><button class="secondary" data-action="close">ปิดหน้าต่าง</button></div>'}</div>`)}
function cancelPrompt(id){const b=state.bookings.find(x=>x.id===id);modal(header('ยกเลิกรายการนี้?')+`<div class="modal-body"><p>รายการ ${b.id} ของ ${esc(b.name)} จะถูกยกเลิก และห้องจะกลับไปใช้สถานะเปิด–ปิดขายเดิม</p>${b.easyfo?'<div class="warning-line">โปรดดำเนินการยกเลิกใน Easyfo ด้วยตนเองด้วย เว็บไซต์ไม่ได้แก้ไข Easyfo ให้อัตโนมัติ</div>':''}<div class="modal-actions"><button class="secondary" data-action="booking" data-id="${id}">กลับ</button><button class="danger" data-action="cancel" data-id="${id}">ยืนยันยกเลิกรายการ</button></div></div>`)}
function showEdit(id){requireAdmin(state);const t=typeBy(id);modal(header('แก้ไข '+t.name,'ข้อมูลจะเปลี่ยนบนหน้าลูกค้าในตัวอย่างนี้ทันที')+`<form id="edit-form" data-id="${id}" class="modal-body"><div class="form-grid"><label>ราคาปกติ / คืน (บาท)<input type="number" name="price" min="100" max="100000" step="1" value="${t.price}" required></label><label>โปรโมชั่นส่วนลด (%)<input type="number" name="discount" min="0" max="50" step="1" value="${t.discount}" required></label><label class="full">คำโปรยห้องพัก<input name="label" value="${esc(t.label)}" maxlength="80" required></label><label class="full">รายละเอียดห้องพัก<textarea name="desc" maxlength="500" required>${esc(t.desc)}</textarea></label><label class="full file-label">รูปห้องพัก (เลือกทดลองได้)<input name="photo" type="file" accept="image/jpeg,image/png,image/webp"><span class="tiny">JPG, PNG หรือ WebP ไม่เกิน 5 MB · อยู่เฉพาะในหน้าเว็บนี้</span></label></div><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">ยกเลิก</button><button class="primary">บันทึกข้อมูลตัวอย่าง</button></div></form>`)}
function resetPrompt(){modal(header('เริ่มตัวอย่างใหม่?')+`<div class="modal-body"><p>ข้อมูลการจอง ราคา รูปภาพ สถานะห้อง และสถิติที่คุณทดลองจะกลับเป็นข้อมูลตัวอย่างเริ่มต้นทั้งหมด</p><div class="modal-actions"><button class="secondary" data-action="close">กลับ</button><button class="primary" data-action="reset-confirm">เริ่มใหม่</button></div></div>`)}
function adminNotice(){return state.role==='admin'?'':`<div class="notice amber">${icon('lock')}<div>หน้านี้เป็นงานของผู้ดูแลโรงแรม <button class="text-button" data-action="try-admin">ทดลองบทบาทผู้ดูแล</button></div></div>`}
function master(){
 const rooms=state.rooms.filter(r=>r.floor===masterFloor).sort((a,b)=>a.order-b.order),ids=layoutDraft[masterFloor]||rooms.map(r=>r.id),admin=state.role==='admin';
 return `${pageTitle('ตั้งค่าห้องและผัง','เก็บเลขห้อง ชั้น และประเภทแยกกัน · หนึ่งชั้นมีหลายประเภทได้')}${adminNotice()}<div class="notice">${icon('info')}<div>จำนวนแยกชั้น เลขห้อง และประเภทใน Demo เป็นข้อมูลสมมติ โดยแบ่ง ${FLOORS.map(f=>'ชั้น '+f+': '+state.rooms.filter(r=>r.floor===f).length+' ห้อง').join(' · ')} รวม 168 ห้อง</div></div><section class="panel"><div class="panel-head"><div><h2>ข้อมูลห้องพัก</h2><p>แก้รายห้อง หรือนำเข้ารายชื่อจาก Excel ที่บันทึกเป็น CSV</p></div><button class="secondary" data-action="import-rooms" ${admin?'':'disabled'}>นำเข้า CSV</button></div>${floorTabs(masterFloor,'master-floor',false)}<div class="catalog-toolbar"><div class="type-tabs"><button class="${masterMode==='catalog'?'active':''}" data-action="master-mode" data-id="catalog">ตารางข้อมูล</button><button class="${masterMode==='layout'?'active':''}" data-action="master-mode" data-id="layout">จัดลำดับผัง</button></div><a class="text-button" href="./assets/room-template.csv" download="Suntara_Grand_Room_Template.csv">ดาวน์โหลด CSV ตัวอย่าง</a></div>${masterMode==='catalog'?`<div class="table-scroll catalog-table"><table><thead><tr><th>เลขห้อง</th><th>ชั้น</th><th>ประเภทห้อง</th><th>ตำแหน่งแสดงผล</th><th></th></tr></thead><tbody>${rooms.map((r,i)=>`<tr><td><strong>${esc(r.id)}</strong></td><td>${r.floor}</td><td>${typeBy(r.type).name}</td><td>${i+1}</td><td><button class="table-action" data-action="edit-room" data-id="${esc(r.id)}" ${admin?'':'disabled'}>แก้ไข</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="layout-explainer">${icon('info',17)} ลากการ์ดเพื่อเรียงลำดับ หรือใช้ปุ่มลูกศรบนมือถือ แล้วกดบันทึก · เปลี่ยนเฉพาะตำแหน่งแสดงผล</div><div class="layout-grid">${ids.map((id,i)=>{const r=state.rooms.find(r=>r.id===id);return `<article class="layout-tile" draggable="${admin}" data-drag-room="${esc(id)}"><span class="drag-handle" aria-hidden="true">⠿</span><strong>${esc(id)}</strong><span>${typeBy(r.type).name}</span><div class="layout-movers"><button data-action="layout-move" data-id="${esc(id)}" data-direction="-1" aria-label="เลื่อนห้อง ${esc(id)} ไปก่อนหน้า" ${!admin||!i?'disabled':''}>←</button><button data-action="layout-move" data-id="${esc(id)}" data-direction="1" aria-label="เลื่อนห้อง ${esc(id)} ไปถัดไป" ${!admin||i===ids.length-1?'disabled':''}>→</button></div></article>`}).join('')}</div><div class="layout-save"><span>${layoutDraft[masterFloor]?'มีการจัดลำดับที่ยังไม่ได้บันทึก':'ลำดับที่บันทึกไว้'} · ชั้น ${masterFloor}</span><div><button class="secondary" data-action="layout-reset" ${!layoutDraft[masterFloor]?'disabled':''}>คืนลำดับเดิม</button><button class="primary" data-action="layout-save" ${!admin||!layoutDraft[masterFloor]?'disabled':''}>บันทึกตำแหน่ง</button></div></div>`}</section><p class="front-foot">ผังนี้แสดงลำดับการ์ดเพื่อค้นหาห้อง ไม่ใช่แปลนอาคารจริง · การเปลี่ยนเลขห้อง ชั้น หรือประเภทของห้องที่มีรายการจองจะถูกป้องกันไว้</p>`;
}
function auditView(){return `${pageTitle('ประวัติการเปลี่ยนแปลง','ตรวจว่าใครทำอะไร เวลาใด และด้วยเหตุผลอะไร')}<div class="notice">${icon('info')}<div>ประวัติใน Demo ใช้ชื่อบทบาทสมมติ อยู่เฉพาะหน้าเว็บนี้ และหายเมื่อรีเฟรช · ยังไม่มีระบบเข้าสู่ระบบจริง</div></div><section class="panel"><div class="panel-head"><h2>กิจกรรมล่าสุด</h2><span class="badge">${state.audit.length} รายการ</span></div><div class="audit-list">${state.audit.map(a=>`<article class="audit-entry"><div><strong>${esc(a.action)}</strong><span>${new Date(a.time).toLocaleString('th-TH',{dateStyle:'short',timeStyle:'medium'})} · ${esc(a.actor)}</span></div><p>${esc(a.detail)}</p></article>`).join('')||'<div class="empty"><h3>ยังไม่มีการเปลี่ยนแปลง</h3><p>ลองเปิด–ปิดห้อง หรือยืนยันรายการจอง แล้วกลับมาดูประวัติได้ที่นี่</p></div>'}</div></section>`}
function showAvailability(ids,open){
 if(!ids.length)return toast('กรุณาเลือกห้อง');pendingBatch={ids:[...ids],open,start:range.start,end:range.end};
 modal(header(open?'เปิดขายห้องที่เลือก':'ปิดขายห้องที่เลือก','ตรวจสอบรายการและวันที่ก่อนบันทึก')+`<form id="availability-form" class="modal-body"><div class="summary-box"><div class="summary-row"><span>จำนวนห้อง</span><strong>${ids.length} ห้อง</strong></div><div class="summary-row"><span>ช่วงวันที่</span><strong>${fmt(range.start)} — ${fmt(range.end)}</strong></div><div class="summary-row"><span>จำนวนคืนที่มีผล</span><strong>${nights(range.start,range.end)} คืน</strong></div></div><div class="selected-room-chips">${ids.map(id=>`<span>${esc(id)}</span>`).join('')}</div>${open?'<div class="notice">ตรวจสอบ Easyfo แล้วว่าห้องเหล่านี้ว่างตลอดช่วงที่เลือก</div>':`<label>เหตุผลที่ปิดขาย<select name="reason" required><option value="">เลือกเหตุผล</option>${CLOSE_REASONS.map(r=>`<option>${r}</option>`).join('')}</select></label>`}<label style="margin-top:15px">หมายเหตุเพิ่มเติม<input name="note" maxlength="120" placeholder="เช่น สำรองให้กรุ๊ปตัวอย่าง"></label><label class="check-label"><input name="ack" type="checkbox" required><span>ตรวจสอบเลขห้องและช่วงวัน${open?'กับ Easyfo แล้ว':'ที่จะปิดขายแล้ว'} และเข้าใจว่าเว็บไซต์ไม่แก้ข้อมูล Easyfo อัตโนมัติ</span></label><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">กลับ</button><button class="primary">ยืนยัน${open?'เปิด':'ปิด'}ขาย ${ids.length} ห้อง</button></div></form>`);
}
function showRoom(id){
 const r=state.rooms.find(x=>x.id===id),s=roomStatus(state,r,range.start,range.end),b=state.bookings.find(b=>b.room===id&&b.status!=='cancelled'&&b.start<range.end&&range.start<b.end);const reasons=new Set();for(let d=range.start;d<range.end;d=addDays(d,1)){const reason=closeReason(r,d);if(reason)reasons.add(reason)}
 modal(header('ห้อง '+esc(r.id),typeBy(r.type).name+' · ชั้น '+r.floor+' · ห้องสมมติ')+`<div class="modal-body"><div class="info-list"><div class="info-item"><span>ช่วงวันที่จัดการ</span><strong>${fmt(range.start)} — ${fmt(range.end)}</strong></div><div class="info-item"><span>สถานะออนไลน์</span>${badge(s)}</div></div>${b?`<div class="status-help">มีรายการ ${b.id} อยู่ จึงไม่สามารถเปิด–ปิดขายทับได้</div><div class="modal-actions"><button class="primary" data-action="booking" data-id="${b.id}">เปิดรายการจอง →</button></div>`:`${reasons.size?`<div class="status-help"><strong>เหตุผลที่ปิดบางคืนหรือทุกคืน</strong><br>${[...reasons].map(esc).join(' · ')}</div>`:''}<p class="tiny" style="margin-top:15px">ใช้ควบคุมการขายออนไลน์ ไม่ใช่สถานะแม่บ้าน และไม่ซิงก์ Easyfo</p><div class="modal-actions"><button class="secondary" data-action="close">ปิดหน้าต่าง</button><button class="primary" data-action="single-availability" data-id="${esc(id)}" data-open="${s==='closed'}">${s==='closed'?'เปิดขายออนไลน์':'ปิดขายออนไลน์'}</button></div>`}</div>`);
}
function showMoveBooking(id){const b=state.bookings.find(b=>b.id===id),options=available(state,b.type,b.start,b.end).filter(r=>r.id!==b.room);modal(header('เปลี่ยนห้องสำหรับ '+b.id,typeBy(b.type).name+' · คงวันพักและราคาเดิม')+`<form class="modal-body" id="move-booking-form" data-id="${b.id}"><div class="summary-box"><div class="summary-row"><span>ห้องเดิม</span><strong>${esc(b.room)} · ชั้น ${state.rooms.find(r=>r.id===b.room)?.floor??'—'}</strong></div><div class="summary-row"><span>วันเข้าพัก</span><strong>${fmt(b.start)} — ${fmt(b.end)}</strong></div><div class="summary-row"><span>ยอดเดิม</span><strong>฿${money(b.total)}</strong></div></div>${options.length?`<label>ห้องใหม่ที่ว่างครบทุกคืน<select name="target" required><option value="">เลือกห้องใหม่</option>${options.map(r=>`<option value="${esc(r.id)}">ห้อง ${esc(r.id)} · ชั้น ${r.floor} · ${typeBy(r.type).name}</option>`).join('')}</select></label><p class="tiny" style="margin-top:12px">แสดงเฉพาะห้องประเภทเดิมที่เปิดขายและว่างตลอดช่วงเข้าพัก</p>${b.easyfo?'<label class="check-label"><input type="checkbox" name="easyfoUpdated" required><span>ตรวจสอบและเปลี่ยนเลขห้องใน Easyfo ด้วยตนเองแล้ว</span></label>':'<div class="status-help">หลังเปลี่ยนห้อง ให้ลงหมายเลขห้องใหม่ใน Easyfo ก่อนยืนยันการจอง</div>'}`:'<div class="empty">ไม่มีห้องประเภทเดียวกันที่ว่างครบทุกคืน</div>'}<div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-action="booking" data-id="${id}">กลับ</button><button class="primary" ${!options.length?'disabled':''}>ยืนยันเปลี่ยนห้อง</button></div></form>`)}
function showEditRoom(id){requireAdmin(state);const r=state.rooms.find(r=>r.id===id);modal(header('แก้ข้อมูลห้อง '+esc(id),'การแก้ไขมีผลต่อข้อมูลห้องและการค้นหาหน้าลูกค้า')+`<form class="modal-body" id="edit-room-form" data-id="${esc(id)}"><div class="form-grid"><label>เลขห้อง<input name="id" value="${esc(r.id)}" pattern="[A-Za-z0-9-]{1,12}" maxlength="12" required></label><label>ชั้น<select name="floor">${FLOORS.map(f=>`<option value="${f}" ${f===r.floor?'selected':''}>ชั้น ${f}</option>`).join('')}</select></label><label class="full">ประเภทห้อง<select name="type">${state.types.map(t=>`<option value="${t.id}" ${t.id===r.type?'selected':''}>${t.name}</option>`).join('')}</select></label></div><div class="status-help">ห้องที่มีรายการจองค้างอยู่ต้องย้ายหรือยกเลิกรายการก่อนแก้ข้อมูลหลัก เพื่อรักษาความถูกต้องของการจอง</div><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">กลับ</button><button class="primary">บันทึกข้อมูลห้อง</button></div></form>`)}
function showImport(){requireAdmin(state);importPreview=null;modal(header('นำเข้ารายชื่อห้องจาก CSV','168 ห้อง · ตรวจสอบข้อมูลก่อนนำเข้า')+`<form class="modal-body" id="import-preview-form"><p>ใช้ Excel บันทึกเป็น CSV UTF-8 หรือคัดลอกตารางมาวาง โดยมีคอลัมน์ room_number, floor, room_type</p><a class="text-button" href="./assets/room-template.csv" download="Suntara_Grand_Room_Template.csv">ดาวน์โหลดไฟล์ตัวอย่าง 168 ห้อง</a><label class="file-label" style="margin-top:15px">เลือกไฟล์ CSV<input id="catalog-file" type="file" accept=".csv,text/csv,text/plain"></label><label style="margin-top:15px">หรือวางข้อมูลจาก Excel<textarea id="catalog-text" name="csv" rows="6" placeholder="room_number,floor,room_type&#10;301,3,Deluxe"></textarea></label><div class="status-help">ประเภท: Deluxe, Grand Deluxe, Superior, Suite · ชั้น: 3–6<br>ห้องที่มีรายการจองอยู่ต้องคงเลขห้อง ชั้น และประเภทเดิม</div><div class="form-error" role="alert"></div><div class="modal-actions"><button type="button" class="secondary" data-action="close">กลับ</button><button class="primary">ตรวจสอบไฟล์ →</button></div></form>`)}
function showImportPreview(rows){importPreview=validateRoomImport(state,rows);modal(header('ตรวจสอบรายชื่อก่อนนำเข้า','ผ่านการตรวจสอบ 168 ห้อง ไม่มีเลขห้องซ้ำ')+`<div class="modal-body"><div class="import-counts">${FLOORS.map(f=>`<span>ชั้น ${f}<strong>${rows.filter(r=>r.floor===f).length} ห้อง</strong></span>`).join('')}</div><div class="table-scroll"><table><thead><tr><th>เลขห้อง</th><th>ชั้น</th><th>ประเภท</th></tr></thead><tbody>${rows.slice(0,5).map(r=>`<tr><td>${esc(r.id)}</td><td>${r.floor}</td><td>${typeBy(r.type).name}</td></tr>`).join('')}</tbody></table></div><p class="tiny">แสดง 5 รายการแรกจาก 168 ห้อง</p><div class="notice amber" style="margin-top:18px">รายชื่อนี้จะแทนข้อมูลห้องชุดเดิม โดยคงรายการจองและสถานะขายของเลขห้องที่ตรงกัน ห้องที่เพิ่มใหม่จะเริ่มปิดขาย</div><div class="form-error" role="alert"></div><div class="modal-actions"><button class="secondary" data-action="import-rooms">กลับไปเลือกไฟล์</button><button class="primary" data-action="apply-import">ยืนยันนำเข้า 168 ห้อง</button></div></div>`)}
function changeLayout(id,offset){requireAdmin(state);const ids=[...(layoutDraft[masterFloor]||state.rooms.filter(r=>r.floor===masterFloor).sort((a,b)=>a.order-b.order).map(r=>r.id))];const index=ids.indexOf(id),target=index+offset;if(index<0||target<0||target>=ids.length)return;ids.splice(index,1);ids.splice(target,0,id);layoutDraft[masterFloor]=ids;render();document.querySelector('[data-action="layout-move"][data-id="'+id+'"][data-direction="'+offset+'"]')?.focus()}

document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
document.querySelector('#brand').addEventListener('click',e=>{e.preventDefault();navigate('guest')});
document.querySelector('#reset').addEventListener('click',resetPrompt);
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id}=b.dataset;try{if(features.handleAction(action,id)){e.preventDefault();return;}switch(action){
 case 'close':dialog.close();break;case 'guest':navigate('guest');break;
 case 'section':section=id;page=1;selectedRooms.clear();render();break;
 case 'type':typeFilter=id;page=1;selectedRooms.clear();render();break;
 case 'booking-filter':bookingFilter=id;render();break;
 case 'prev':page--;render();break;case 'next':page++;render();break;
 case 'detail':showDetail(id);break;case 'book':showBook(id);break;
 case 'room':showRoom(id);break;case 'booking':showBooking(id);break;

 case 'open-front-booking':dialog.close();navigate('front','bookings');showBooking(id);break;
 case 'confirm':confirmBooking(state,id);render();showBooking(id);toast('ยืนยันการจองตัวอย่างแล้ว');break;
 case 'cancel-prompt':cancelPrompt(id);break;case 'cancel':cancelBooking(state,id);render();showBooking(id);toast('ยกเลิกรายการในเว็บไซต์ตัวอย่างแล้ว');break;
 case 'edit':showEdit(id);break;
 case 'floor':floorFilter=id==='all'?'all':Number(id);page=1;selectedRooms.clear();render();break;
 case 'clear-filters':floorFilter='all';typeFilter=statusFilter='all';roomQuery='';selectedRooms.clear();page=1;render();break;
 case 'clear-selection':selectedRooms.clear();render();break;
 case 'bulk':showAvailability([...selectedRooms],b.dataset.open==='true');break;
 case 'single-availability':showAvailability([id],b.dataset.open==='true');break;
 case 'move-booking':showMoveBooking(id);break;
 case 'try-admin':state.role='admin';render();toast('สลับเป็นผู้ดูแล Demo แล้ว');break;
 case 'master-floor':masterFloor=Number(id);render();break;
 case 'master-mode':masterMode=id;render();break;
 case 'edit-room':showEditRoom(id);break;
 case 'import-rooms':showImport();break;
 case 'apply-import':importRooms(state,importPreview);layoutDraft={};selectedRooms.clear();importPreview=null;dialog.close();render();toast('นำเข้ารายชื่อครบ 168 ห้องแล้ว');break;
 case 'layout-move':changeLayout(id,Number(b.dataset.direction));break;
 case 'layout-reset':delete layoutDraft[masterFloor];render();break;
 case 'layout-save':saveRoomOrder(state,masterFloor,layoutDraft[masterFloor]);delete layoutDraft[masterFloor];render();toast('บันทึกตำแหน่งการ์ดแล้ว');break;
 case 'reset-confirm':for(const t of state.types)if(t.photo.startsWith('blob:'))URL.revokeObjectURL(t.photo);state=makeState();search={start:state.start,end:state.end,guests:2,type:'all'};range={start:state.start,end:state.end};typeFilter=statusFilter=bookingFilter='all';floorFilter=masterFloor=3;masterMode='catalog';roomQuery='';layoutDraft={};pendingBatch=importPreview=null;selectedRooms.clear();page=1;features.reset();dialog.close();render();toast('คืนข้อมูลตัวอย่างเริ่มต้นแล้ว');break;
 }}catch(err){error(err.message)}});
document.addEventListener('change',async e=>{try{
 if(e.target.id==='calendar-type'){features.setCalendarType(e.target.value);document.querySelector('#calendar-type')?.focus();return}
 if(e.target.id==='demo-role'){state.role=e.target.value==='admin'?'admin':'front';render();toast('กำลังทดลองบทบาท '+(state.role==='admin'?'ผู้ดูแล':'Front'))}
 if(e.target.id==='status-filter'){statusFilter=e.target.value;page=1;selectedRooms.clear();render()}
 if(e.target.dataset.roomSelect){const id=e.target.dataset.roomSelect;e.target.checked?selectedRooms.add(id):selectedRooms.delete(id);render();document.querySelector('[data-room-select="'+id+'"]')?.focus()}
 if(e.target.id==='select-filtered'){const checked=e.target.checked;for(const r of filteredRooms().filter(selectableRoom))checked?selectedRooms.add(r.id):selectedRooms.delete(r.id);render();document.querySelector('#select-filtered')?.focus()}
 if(e.target.name==='start'&&e.target.value){const f=e.target.closest('form'),end=f?.elements.namedItem('end');if(end){end.min=addDays(e.target.value,1);if(end.value<=e.target.value)end.value=end.min}}
 if(e.target.id==='catalog-file'){const file=e.target.files[0];if(file){if(file.size>500000)throw Error('ไฟล์ต้องไม่เกิน 500 KB');const value=await file.text();const field=document.querySelector('#catalog-text');if(field)field.value=value}}
 }catch(err){error(err.message)}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,data=new FormData(form),values=Object.fromEntries(data);try{switch(form.id){
 case 'search-form':validStay(values.start,values.end);search={start:values.start,end:values.end,guests:Number(values.guests),type:values.type||'all'};features.afterSearch();render();document.querySelector('#rooms').scrollIntoView({behavior:'smooth',block:'start'});toast('อัปเดตห้องพักตามวันที่เลือกแล้ว');break;
 case 'range-form':validStay(values.start,values.end);range={start:values.start,end:values.end};selectedRooms.clear();page=1;render();toast('อัปเดตสถานะห้องตามวันที่เลือกแล้ว');break;
 case 'room-search':roomQuery=values.query.trim();page=1;selectedRooms.clear();render();break;
 case 'availability-form':{if(!pendingBatch||!values.ack)throw Error('กรุณายืนยันข้อมูลก่อนบันทึก');const action=pendingBatch;setRoomsOpen(state,action.ids,action.start,action.end,action.open,(action.open?'ตรวจสอบ Easyfo แล้ว':values.reason)+(values.note?' · '+values.note:''));pendingBatch=null;selectedRooms.clear();dialog.close();render();toast('อัปเดตสถานะ '+action.ids.length+' ห้องแล้ว');break}
 case 'move-booking-form':moveBooking(state,form.dataset.id,values.target,values.easyfoUpdated==='on');render();showBooking(form.dataset.id);toast('เปลี่ยนห้องแล้ว โดยคงวันพักและราคาเดิม');break;
 case 'edit-room-form':updateRoom(state,form.dataset.id,values);layoutDraft={};selectedRooms.clear();dialog.close();render();toast('อัปเดตข้อมูลห้องแล้ว');break;
 case 'import-preview-form':showImportPreview(parseRoomCSV(values.csv));break;
 case 'book-form':{const booking=createBooking(state,{...search,type:form.dataset.id,name:values.name,phone:values.phone});features.record('booking_request',booking.type);render();bookingSuccess(booking);break}
 case 'easyfo-form':saveEasyfo(state,form.dataset.id,values.reference);render();showBooking(form.dataset.id);toast('บันทึกการลง Easyfo แล้ว');break;
 case 'edit-form':{requireAdmin(state);const t=typeBy(form.dataset.id),p=Number(values.price),d=Number(values.discount),file=data.get('photo');if(!Number.isInteger(p)||p<100||p>100000||!Number.isInteger(d)||d<0||d>50)throw Error('กรุณาตรวจสอบราคาและส่วนลด');if(!values.label.trim()||!values.desc.trim())throw Error('กรุณากรอกคำโปรยและรายละเอียด');if(file.size>5*1024*1024)throw Error('กรุณาเลือกรูปขนาดไม่เกิน 5 MB');if(file.size&&!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('กรุณาเลือกไฟล์ JPG, PNG หรือ WebP');t.price=p;t.discount=d;t.label=values.label.trim();t.desc=values.desc.trim();if(file.size){if(t.photo.startsWith('blob:'))URL.revokeObjectURL(t.photo);t.photo=URL.createObjectURL(file)}audit(state,'แก้ราคาและข้อมูลห้อง',t.name+' · ราคา '+p+' บาท / คืน · ส่วนลด '+d+'%');dialog.close();render();toast('บันทึกแล้ว ลองดูผลที่หน้าจองลูกค้าได้เลย');break}
 }}catch(err){if(dialog.open)error(err.message);else toast(err.message)}});
let draggedRoom=null;
 document.addEventListener('dragstart',e=>{const tile=e.target.closest('[data-drag-room]');if(!tile||state.role!=='admin')return;draggedRoom=tile.dataset.dragRoom;e.dataTransfer.setData('text/plain',draggedRoom);e.dataTransfer.effectAllowed='move';tile.classList.add('dragging')});
 document.addEventListener('dragover',e=>{if(draggedRoom&&e.target.closest('[data-drag-room]')){e.preventDefault();e.dataTransfer.dropEffect='move'}});
 document.addEventListener('drop',e=>{const tile=e.target.closest('[data-drag-room]');if(!draggedRoom||!tile||state.role!=='admin')return;e.preventDefault();const target=tile.dataset.dragRoom;const ids=layoutDraft[masterFloor]||state.rooms.filter(r=>r.floor===masterFloor).sort((a,b)=>a.order-b.order).map(r=>r.id);const from=ids.indexOf(draggedRoom),to=ids.indexOf(target);if(from>=0&&to>=0&&from!==to)changeLayout(draggedRoom,to-from);draggedRoom=null});
 document.addEventListener('dragend',()=>{draggedRoom=null;document.querySelectorAll('.dragging').forEach(el=>el.classList.remove('dragging'))});
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
render();
