if(document.modelContext?.registerTool){const lifecycle=new AbortController();const schemas={view:{type:'object',properties:{view:{type:'string',enum:['guest','front']},section:{type:'string',enum:['inventory','bookings','settings','master','analytics','audit','guide']}},required:['view'],additionalProperties:false},availability:{type:'object',properties:{start:{type:'string'},end:{type:'string'},guests:{type:'integer',minimum:1,maximum:4}},required:['start','end','guests'],additionalProperties:false}};
 const tools=[{name:'navigate_hotel_demo',title:'เปิดหน้าจอตัวอย่างโรงแรม',description:'Navigate to the guest or Front prototype screen; does not create a booking.',inputSchema:schemas.view,annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['guest','front'].includes(input.view)||(input.section&&!['inventory','bookings','settings','master','analytics','audit','guide'].includes(input.section)))throw Error('Invalid view');dialog.close();navigate(input.view,input.section);return {view,section:view==='front'?section:null,demo:true}}},{name:'search_demo_room_availability',title:'ค้นหาห้องว่างตัวอย่าง',description:'Update the guest search and return availability and sample rates. Does not reserve rooms.',inputSchema:schemas.availability,annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Number.isInteger(input.guests)||input.guests<1||input.guests>4)throw Error('Invalid guests');validStay(input.start,input.end);search={start:input.start,end:input.end,guests:input.guests,type:'all'};features.afterSearch();dialog.close();navigate('guest');return {demo:true,rooms:state.types.filter(t=>t.capacity>=input.guests).map(t=>({type:t.name,available:available(state,t.id,input.start,input.end).length,nightlyRate:rate(t),currency:'THB'}))}}}];
 for(const tool of tools)try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{})}catch{}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
